import heapq

def solve_ferry_timetable(text):
    vals = list(map(int, text.split()))
    n, m = vals[0], vals[1]
    out = [[] for _ in range(n + 1)]
    for k in range(2, 2 + 4 * m, 4):
        a, b, t, p = vals[k:k + 4]
        out[a].append((b, t, p))
    best = [None] * (n + 1)
    best[1] = 0
    heap = [(0, 1)]
    while heap:
        now, u = heapq.heappop(heap)
        if now > best[u]:
            continue
        if u == n:
            return str(now)
        for v, t, p in out[u]:
            arrive = (now + p - 1) // p * p + t
            if best[v] is None or arrive < best[v]:
                best[v] = arrive
                heapq.heappush(heap, (arrive, v))
    return '-1'

